(function(){document.querySelectorAll('.p-FB-13-2').forEach(function(r){var l=r.querySelector('.launcher'),ll=l.querySelector('.ll'),p=r.querySelector('.panel'),q=r.querySelector('.q'),items=[].slice.call(r.querySelectorAll('.menu .mi')),none=r.querySelector('.none'),at=r.querySelector('[data-at]'),ab=r.querySelector('[data-ab]'),f=r.querySelector('.composer'),inp=f.querySelector('input'),log=r.querySelector('.log');function view(v,el){p.setAttribute('data-view',v);if(el)setTimeout(function(){el.focus();},0);}function set(o){r.classList.toggle('is-open',o);l.setAttribute('aria-expanded',o?'true':'false');ll.textContent=o?'閉じる':'ヘルプ';if(o)view('home',q);}l.addEventListener('click',function(){set(!r.classList.contains('is-open'));});r.addEventListener('keydown',function(e){if(e.key==='Escape'&&r.classList.contains('is-open')){set(false);l.focus();}});q.addEventListener('input',function(){var s=q.value.trim(),c=0;items.forEach(function(li){var m=li.textContent.indexOf(s)>-1;li.hidden=!m;if(m)c++;});none.hidden=c>0;});items.forEach(function(li){var b=li.querySelector('button');b.addEventListener('click',function(){at.textContent=b.dataset.title;ab.textContent=b.dataset.body;view('article',r.querySelector('.v-article [data-back]'));});});r.querySelectorAll('[data-start]').forEach(function(b){b.addEventListener('click',function(){view('chat',inp);});});r.querySelectorAll('[data-back]').forEach(function(b){b.addEventListener('click',function(){view('home',q);});});f.addEventListener('submit',function(e){e.preventDefault();var v=inp.value.trim();if(!v)return;var li=document.createElement('li');li.className='msg out';li.textContent=v;log.appendChild(li);inp.value='';log.scrollTop=log.scrollHeight;setTimeout(function(){var a=document.createElement('li');a.className='msg in';a.textContent='担当者におつなぎします。少々お待ちください。';log.appendChild(a);log.scrollTop=log.scrollHeight;},1000);});});})();

/* FB-13-3 */
(function(){document.querySelectorAll('.p-FB-13-3').forEach(function(r){var l=r.querySelector('.launcher'),c=r.querySelector('.close'),cta=r.querySelector('.cta');function set(o,f){r.classList.toggle('is-open',o);l.setAttribute('aria-expanded',o?'true':'false');if(o){r.classList.add('is-seen');l.setAttribute('aria-label','お知らせを閉じる');setTimeout(function(){cta.focus();},0);}else{l.setAttribute('aria-label','お知らせを開く');if(f)l.focus();}}l.addEventListener('click',function(){set(!r.classList.contains('is-open'));});c.addEventListener('click',function(){set(false,true);});cta.addEventListener('click',function(){set(false,true);});r.addEventListener('keydown',function(e){if(e.key==='Escape'&&r.classList.contains('is-open'))set(false,true);});});})();

/* FB-14-1 */
(function(){document.querySelectorAll('.p-FB-14-1').forEach(function(r){var no=r.querySelector('[data-no]'),ta=r.querySelector('.ta'),dt=r.querySelector('.dt');function step(s){r.setAttribute('data-step',s);var re=s==='reason';no.classList.toggle('is-selected',re);no.setAttribute('aria-expanded',re?'true':'false');}r.querySelector('[data-yes]').addEventListener('click',function(){step('done');dt.textContent='ご協力ありがとうございました';});no.addEventListener('click',function(){if(r.getAttribute('data-step')==='reason'){step('ask');return;}step('reason');setTimeout(function(){ta.focus();},0);});r.querySelector('[data-cancel]').addEventListener('click',function(){step('ask');no.focus();});r.querySelector('.form').addEventListener('submit',function(e){e.preventDefault();step('done');dt.textContent='送信しました。改善に役立てます';});});})();

/* FB-14-2 */
(function(){document.querySelectorAll('.p-FB-14-2 .report').forEach(function(a){a.addEventListener('click',function(e){e.preventDefault();});});})();

/* CONT-01-5 */
(function(){document.querySelectorAll('.p-CONT-01-5').forEach(function(root){if(root.dataset.ready){return;}root.dataset.ready='1';var stage=root.querySelector('.stage');var cards=Array.prototype.slice.call(stage.querySelectorAll('.card'));var cur=root.querySelector('.cur');function update(){var step=cards[0].offsetHeight+(parseFloat(getComputedStyle(cards[0]).marginBottom)||0);if(!step){return;}var idx=Math.min(cards.length-1,Math.floor((stage.scrollTop+stage.clientHeight*0.5)/step));cur.textContent=String(idx+1);cards.forEach(function(c,i){c.classList.toggle('is-under',i<idx);});}stage.addEventListener('scroll',update,{passive:true});update();});})();

/* CONT-03-3 */
(function(){document.querySelectorAll('.p-CONT-03-3').forEach(function(root){if(root.dataset.ready){return;}root.dataset.ready='1';var vid=root.querySelector('.vid');var play=root.querySelector('.play');var pause=root.querySelector('.pause');play.addEventListener('click',function(){vid.classList.add('is-playing');pause.focus();});pause.addEventListener('click',function(){vid.classList.remove('is-playing');play.focus();});});})();

